// Account-intelligence acceptance over the real STDIO MCP server, across Classic Era, TBC Anniversary, Forever,
// and Retail. Classic data comes from GearExport 2c5e9b3 SavedVariables generated by the unmodified collectors
// (core/test/fixtures/gearexport-2c5e9b3) and travels through the real bridge parser. The Era file is shifted to
// the wall clock so it reads as current; the TBC file keeps its original (stale) timestamps so it reads as
// historical. Automated fixtures only: this is not live client validation.
import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import { mkdtempSync, readFileSync, rmSync } from "node:fs";
import os from "node:os";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { test } from "node:test";
import { Client } from "@modelcontextprotocol/client";
import { StdioClientTransport } from "@modelcontextprotocol/client/stdio";
import { SqliteSnapshotStore } from "@wowsync-dashboard/core";
import { buildWowSyncExport } from "../../core/test/fixtureBuilder.ts";
import { parseSavedExports } from "../../server/src/importSaved.ts";

const packageRoot = path.resolve(fileURLToPath(new URL("../", import.meta.url)));
const entrypoint = path.join(packageRoot, "src", "index.ts");
const FIXTURES = new URL("../../core/test/fixtures/gearexport-2c5e9b3/", import.meta.url);
const GENERATED = 1_789_000_005;
type Obj = Record<string, any>;

function savedRecord(flavor: "classic-era" | "tbc-anniversary", shiftTo?: number) {
  let lua = readFileSync(new URL(`WoWSync-${flavor}.lua`, FIXTURES), "utf8");
  if (shiftTo !== undefined) lua = lua.replace(/\b178900\d{4}\b/g, (value) => String(Number(value) - GENERATED + shiftTo));
  const [record] = parseSavedExports(lua, `${flavor}.lua`);
  return record!;
}

function structured<T>(result: { isError?: boolean; structuredContent?: unknown }): T {
  assert.equal(result.isError, undefined, JSON.stringify(result).slice(0, 600));
  return result.structuredContent as T;
}

test("ACCOUNT INTELLIGENCE: MCP answers practical questions per version with honest evidence labels", async () => {
  const dir = mkdtempSync(path.join(os.tmpdir(), "wowsync-account-intelligence-"));
  const databasePath = path.join(dir, "fixture.sqlite");
  const now = Math.floor(Date.now() / 1000);
  const writer = new SqliteSnapshotStore(databasePath);
  try {
    const era = savedRecord("classic-era", now - 120);
    (era.characterState as Obj).talents.data.unspent = 2;
    const eraTalentTree = (era.characterState as Obj).talents.data.trees as Obj[];
    eraTalentTree[0]!.pointsSpent = 99; // Deliberately conflict with Era [CHARACTER] talentTree to prove the adapter flags it.
    era.text = era.text!.replace("Client: 1.15.9 build 69547\n", "Client: 1.15.9 build 69547\nGUID: Player-4385-ABCD1234\nTalentStatus: OBSERVED\ntalentTree\tname\tpointsSpent\ntalentTree\tElemental\t0\ntalentTree\tEnhancement\t21\ntalentTree\tRestoration\t9\n");
    assert.equal(writer.importSnapshot(era.text!, { characterState: era.characterState }).characterState, "recorded");
    writer.importSnapshot(buildWowSyncExport({ generatedAt: now - 300, character: { name: "Banko", realm: "Nightslayer", class: "Warrior", level: 20, clientVersion: "1.15.9", clientBuild: "69547" },
      bags: { containers: [{ id: 0, capacity: 16, items: [{ itemRef: "item:2840::::::::20:::::::::", name: "Copper Bar", qty: 40 }] }] }, bank: { unknown: true } }));
    const tbc = savedRecord("tbc-anniversary");
    assert.equal(writer.importSnapshot(tbc.text!, { characterState: tbc.characterState }).characterState, "recorded");
    const smithText = buildWowSyncExport({ generatedAt: now - 60, character: { name: "Smith", realm: "Forever Launch", class: "Warrior", level: 8, clientFamily: "Forever", clientVersion: "1.61.0", clientBuild: "71234", interface: "16100", compatibility: "UNVERIFIED_BUILD", compatibilityNote: "Forever project identified; this client build has not been compatibility-tested. Each observation remains API-guarded." } });
    writer.importSnapshot(smithText, { foreverGearObservation: {
      clientProfile: "Forever:1.61.0:71234:16100", name: "Smith", realm: "Forever Launch", generatedAt: now - 60,
      quests: { observedAt: now - 60, completeness: "partial", data: { formatVersion: 1, activeState: "OBSERVED", active: [], completedHistory: { state: "UNKNOWN" } } },
      reputation: { observedAt: now - 60, completeness: "partial", data: { formatVersion: 1, factions: [] } },
      talents: { observedAt: now - 60, completeness: "complete", data: { formatVersion: 1, trees: [{ name: "Arms", pointsSpent: 0, talents: [] }] } },
    } });
    writer.importSnapshot(buildWowSyncExport({ generatedAt: now - 60, character: { name: "Virek", realm: "Cairne", class: "Paladin", level: 80, clientFamily: "Retail", clientVersion: "12.0.5", clientBuild: "60000", interface: "120005" } }));
  } finally {
    writer.close();
  }
  const before = createHash("sha256").update(readFileSync(databasePath)).digest("hex");

  const client = new Client({ name: "wowsync-account-intelligence-test", version: "0.1.0" });
  const eraClient = new Client({ name: "wowsync-account-intelligence-era-test", version: "0.1.0" });
  const transport = new StdioClientTransport({ command: process.execPath, args: [entrypoint], cwd: packageRoot, env: { ...process.env, WOWSYNC_MCP_PROFILE: "forever", WOWSYNC_MCP_DB_PATH: databasePath }, stderr: "pipe" });
  const eraTransport = new StdioClientTransport({ command: process.execPath, args: [entrypoint], cwd: packageRoot, env: { ...process.env, WOWSYNC_MCP_PROFILE: "classic-era", WOWSYNC_MCP_DB_PATH: databasePath }, stderr: "pipe" });
  try {
    await client.connect(transport);
    await eraClient.connect(eraTransport);
    const call = async <T = Obj>(name: string, args: Record<string, unknown>) => structured<T>(await client.callTool({ name, arguments: args }));
    const eraCall = async <T = Obj>(name: string, args: Record<string, unknown>) => structured<T>(await eraClient.callTool({ name, arguments: { ...args, ...(typeof args.name === "string" && args.realm === undefined ? { realm: "Nightslayer" } : {}) } }));

    // Classic Era: "What can Torahn make, and is it learned?"
    const professions = await eraCall("get_character_professions", { version: "classic-era", name: "Torahn" });
    assert.equal(professions.value.data.recipeKnowledge.evidence.state, "OBSERVED");
    const copper = await eraCall("find_recipe_crafters", { version: "classic-era", nameContains: "copper" });
    assert.ok(copper.data.learned.every((row: Obj) => row.recipe.knowledgeClass === "LEARNED" && row.name === "Torahn"));
    assert.deepEqual(copper.data.charactersWithoutRecipeEvidence.map((row: Obj) => row.name), ["Banko"], "no capture is UNKNOWN, not 'cannot craft'");
    const enchant = await eraCall("find_recipe_crafters", { version: "classic-era", enchantID: 7418 });
    assert.deepEqual([enchant.data.learned.length, enchant.data.unresolved[0].recipe.knowledgeClass, enchant.data.unresolved[0].recipe.outputKind], [0, "VISIBLE_LEARNED_UNKNOWN", "ENCHANTMENT"]);

    // "Can Torahn make the vest right now? Where are the bars?"
    const vest = await eraCall("get_recipe_reagent_availability", { version: "classic-era", name: "Torahn", outputItemID: 10421 });
    const bars = vest.value.data.reagents[0].perAlternative[0];
    assert.equal(bars.carriedConclusion, "INSUFFICIENT_IN_COMPLETE_CURRENT_BAGS");
    const owner = (scope: string, name: string) => bars.holdings.find((row: Obj) => row.ownerScope === scope && row.name === name);
    assert.deepEqual([owner("CRAFTER_BAGS", "Torahn").state, owner("CRAFTER_BAGS", "Torahn").quantity, owner("CRAFTER_BAGS", "Torahn").freshness], ["OBSERVED", 3, "recent"]);
    assert.equal(owner("CRAFTER_BANK", "Torahn").state, "UNKNOWN");
    assert.deepEqual([owner("OTHER_CHARACTER", "Banko").quantity, owner("OTHER_CHARACTER", "Banko").usableForCraftingWithoutMove], [40, false]);
    assert.equal(vest.value.data.craftability, "NOT_ESTABLISHED");

    // "Where am I on quests / reputation / talents?"
    const eraQuests = await eraCall("get_character_quests", { version: "classic-era", name: "Torahn", completedQuestIDs: [870, 999] });
    assert.equal(eraQuests.value.data.state, "OBSERVED");
    assert.deepEqual(eraQuests.value.data.completedHistory.lookup.map((row: Obj) => row.state), ["OBSERVED", "NOT_IN_RETURNED_HISTORY"]);
    const progression = await eraCall("get_character_progression", { version: "classic-era", name: "Torahn", factionQuery: "thunder" });
    assert.deepEqual(progression.value.data.reputation.factions.map((row: Obj) => [row.name, row.standingLabel]), [["Thunder Bluff", "Honored"]]);
    assert.equal(progression.value.data.talents.distribution, "99/21/9");
    assert.equal(progression.value.data.talents.unspentPoints, 2);
    assert.deepEqual(progression.value.data.talentTreeAgreement, { state: "DISAGREEMENT", mismatches: [{ tree: "Elemental", characterPointsSpent: 0, talentsPointsSpent: 99 }] });
    const eraState = await eraCall("get_character_state", { version: "classic-era", name: "Torahn" });
    assert.deepEqual(Object.fromEntries(Object.entries(eraState.value.data.structuredObservations).map(([key, value]) => [key, (value as Obj).state])), { recipes: "OBSERVED", quests: "OBSERVED", reputation: "OBSERVED", talents: "OBSERVED" });

    // TBC Anniversary: the same name on another version is a separate identity; its old capture is historical.
    const tbcQuests = await call("get_character_quests", { version: "tbc-anniversary", name: "Torahn" });
    assert.equal(tbcQuests.value.data.state, "LAST_SEEN", "a month-old quest log is not current");
    const tbcVest = await call("get_recipe_reagent_availability", { version: "tbc-anniversary", name: "Torahn", outputItemID: 10421 });
    assert.equal(tbcVest.value.data.reagents[0].perAlternative[0].carriedConclusion, "UNKNOWN", "stale bags never support a current conclusion");
    const tbcCrafters = await call("find_recipe_crafters", { version: "tbc-anniversary", outputItemID: 2853 });
    assert.deepEqual(tbcCrafters.data.learned.map((row: Obj) => row.identityKey), ["tbc-anniversary::dreamscythe::torahn"]);

    // Forever launch build: accepted, unverified by the Dashboard, and the exporter agrees.
    const smith = await call("get_character_state", { version: "forever", name: "Smith" });
    assert.deepEqual(smith.value.data.structuredObservations.clientCompatibility, { dashboard: "UNVERIFIED_BUILD", exporter: "UNVERIFIED_BUILD", exporterNote: "Forever project identified; this client build has not been compatibility-tested. Each observation remains API-guarded.", agreement: "AGREE" });
    assert.deepEqual(Object.fromEntries(Object.entries(smith.value.data.structuredObservations).filter(([key]) => ["recipes", "quests", "reputation", "talents"].includes(key)).map(([key, value]) => [key, (value as Obj).state])), { recipes: "UNKNOWN", quests: "OBSERVED", reputation: "OBSERVED", talents: "OBSERVED" });
    const smithProgression = await call("get_character_progression", { version: "forever", name: "Smith" });
    assert.equal(smithProgression.value.data.talents.trees[0].pointsSpent, 0, "an observed zero point total stays distinct from UNKNOWN");

    // Retail: no quest/progression capture is claimed; no Classic rows leak in.
    const retailQuests = await call("get_character_quests", { version: "retail", name: "Virek" });
    assert.equal(retailQuests.value.provenance.state, "UNKNOWN");
    const retailCrafters = await call("find_recipe_crafters", { version: "retail", outputItemID: 2853 });
    assert.deepEqual(retailCrafters.data.learned, []);
  } finally {
    await eraClient.close();
    await client.close();
  }
  assert.equal(createHash("sha256").update(readFileSync(databasePath)).digest("hex"), before, "every call is read-only");
  rmSync(dir, { recursive: true, force: true });
});
